const $=id=>document.getElementById(id);
const canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false});
const FOV=1.12,MAP=32;
let W=0,H=0,dpr=1,last=0,time=0,playing=false,paused=false,gameEnd=false,aiming=false,mouseDown=false,shake=true,sens=1,team='ussr',weaponIndex=0,weaponTimer=0,reloadTimer=0,lastShot=0,lastDamage=0,toastTimer=0,toastText='',scoreUSSR=50,scoreGermany=50;
const keys=Object.create(null),tracers=[],aircraft=[];
const weapons=[{name:'MOSIN–NAGANT',caption:'BOLT-ACTION RIFLE',mag:5,reserve:35,rate:.72,damage:55,range:28},{name:'PPSh-41',caption:'SUBMACHINE GUN',mag:35,reserve:140,rate:.105,damage:22,range:19},{name:'DP-27',caption:'LIGHT MACHINE GUN',mag:47,reserve:188,rate:.13,damage:27,range:24}];
let grid=[],zones=[],bots=[],vehicles=[],emplacements=[],crates=[];
const player={x:4.5,y:16.5,a:0,hp:100,mag:5,reserve:35,vehicle:null,emplacement:null,dead:false};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px'}
addEventListener('resize',resize);resize();
function buildMap(){grid=Array.from({length:MAP},(_,y)=>Array.from({length:MAP},(_,x)=>x===0||y===0||x===MAP-1||y===MAP-1?1:0));for(let x=5;x<27;x++)if(x<12||x>18)grid[8][x]=1;for(let x=4;x<28;x++)if(x<10||x>21)grid[23][x]=1;for(let y=10;y<22;y++)if(y<14||y>18)grid[y][15]=1;for(const [x,y] of [[8,12],[9,12],[22,19],[23,19],[5,19],[26,12],[12,5],[19,26],[4,7],[27,24]])grid[y][x]=2}
function startGame(faction){team=faction;playing=true;paused=false;gameEnd=false;scoreUSSR=scoreGermany=50;buildMap();zones=[{id:'A',x:10.5,y:10.5,owner:null,progress:0},{id:'B',x:16.5,y:16.5,owner:null,progress:0},{id:'C',x:22.5,y:21.5,owner:null,progress:0},{id:'BASE',x:faction==='ussr'?27.5:4.5,y:16.5,owner:faction==='ussr'?'germany':'ussr',progress:0}];player.x=faction==='ussr'?4.5:27.5;player.y=16.5;player.a=faction==='ussr'?0:Math.PI;player.hp=100;player.dead=false;player.vehicle=null;player.emplacement=null;weaponIndex=0;weapons.forEach(w=>{w.mag=w.name==='MOSIN–NAGANT'?5:w.name==='PPSh-41'?35:47;w.reserve=w.name==='MOSIN–NAGANT'?35:w.name==='PPSh-41'?140:188});bots=[];for(let i=0;i<20;i++){let side=i<10?'ussr':'germany',sx=side==='ussr'?5+Math.random()*5:22+Math.random()*5,sy=5+Math.random()*22;bots.push({x:sx,y:sy,team:side,hp:100,alive:true,cooldown:Math.random()*1,respawn:0,walk:Math.random()*8})}vehicles=[{kind:'T-34',x:8.5,y:16.5,angle:0,team:'ussr',hp:100},{kind:'PANZER IV',x:23.5,y:16.5,angle:Math.PI,team:'germany',hp:100},{kind:'MOTORBIKE',x:16.5,y:7.5,angle:Math.PI/2,team:'neutral',hp:75}];emplacements=[{x:12.5,y:14.5,team:'ussr',used:false},{x:19.5,y:18.5,team:'germany',used:false}];crates=[{x:7.5,y:20.5},{x:24.5,y:11.5}];aircraft.length=0;tracers.length=0;showScreen(null);$('hud').classList.remove('hidden');$('mapPanel').style.display='block';document.exitPointerLock?.();toast('Capture A, B and C. Push to the enemy base.');updateHud();if(innerWidth>750)canvas.requestPointerLock?.()}
function showScreen(id){for(const screen of document.querySelectorAll('.screen'))screen.classList.toggle('hidden',screen.id!==id);if(!id)$('hud').classList.remove('hidden');else $('hud').classList.add('hidden')}
